function addr(x) {
  if (!x) return '';
  if (typeof x === 'string') {
    const m = x.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
    return (m ? m[0] : x).trim();
  }
  if (x.text) return addr(x.text);
  if (Array.isArray(x.value) && x.value[0]) return addr(x.value[0].address || x.value[0]);
  if (x.address) return String(x.address).trim();
  return String(x).trim();
}
const m = $input.first().json || {};
const meta = m.metadata || {};
const from = addr(m.from || meta.from || m.fromAddress || '').toLowerCase();
const subject = String(m.subject || meta.subject || '').trim();
let body = String(m.textPlain || m.text || m.textAsHtml || '').trim();
if (!body && (m.html || m.textHtml)) {
  body = String(m.html || m.textHtml).replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim();
}
if (!from) return [];
if (from === 'info@themobileprof.com') return [];
if (/mailer-daemon|no-?reply|postmaster/i.test(from)) return [];
if (/n8n smoke/i.test(subject)) return [];
if (!body) body = '(empty body)';
const task_description = [
  'Draft a short plain-text reply as TheMobileProf from info@themobileprof.com.',
  'Do not claim the email was sent. No markdown. Keep it under 250 words.',
  '',
  'From: ' + from,
  'Subject: ' + (subject || '(no subject)'),
  '',
  body.slice(0, 8000)
].join('\n');
return [{
  json: {
    department: 'growth',
    from,
    subject,
    task_description,
    context_data: {
      channel: 'email',
      department: 'growth',
      from,
      subject
    }
  }
}];

const worker = $input.first().json;
const prep = $('Prepare inbound').item.json;
let text = String(worker.output_text || 'Could not draft a reply.');
text = text.replace(/^#{1,6}\s+/gm, '').replace(/\*\*/g, '').replace(/\*/g, '').trim();
let subject = prep.subject || '(no subject)';
if (!/^re:\s/i.test(subject)) subject = 'Re: ' + subject;
return [{
  json: {
    action: 'store',
    to: prep.from,
    subject,
    text,
    from_original: prep.from,
    subject_original: prep.subject
  }
}];

const worker = $('Call growth').item.json;
const prep = $('Prepare inbound').item.json;
const sd = worker.structured_data || {};
let email = String(sd.email || prep.from || '').trim();
let name = String(sd.contact_name || sd.name || '').trim();
if (!name && email.includes('@')) name = email.split('@')[0];
return [{ json: {
  contact_name: name,
  email,
  phone: String(sd.phone || '').trim(),
  company_name: String(sd.company_name || '').trim(),
  pipeline_stage: String(sd.pipeline_stage || 'new'),
  notes: ('Inbound email: ' + (prep.subject || '')).slice(0, 500),
  source: 'email'
} }];
